DROP POLICY IF EXISTS "Anyone can delete player photos" ON storage.objects;
DROP POLICY IF EXISTS "Anyone can update player photos" ON storage.objects;
DROP POLICY IF EXISTS "Authenticated users can delete calendar files" ON storage.objects;
DROP POLICY IF EXISTS "Authenticated users can upload calendar files" ON storage.objects;
DROP POLICY IF EXISTS "Anyone can view calendar files" ON storage.objects;
DROP POLICY IF EXISTS "Anyone can view player photos" ON storage.objects;
CREATE POLICY "Admins can delete player photos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'player-photos' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can update player photos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'player-photos' AND public.has_role(auth.uid(), 'admin')) WITH CHECK (bucket_id = 'player-photos' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can upload calendar files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'calendar-files' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Admins can delete calendar files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'calendar-files' AND public.has_role(auth.uid(), 'admin'));